-- Conferência DEPOIS da 0014. SOMENTE LEITURA. Esperado: todas as linhas "ok_*" = sim e as "digital_*" idênticas às de antes.
select 'ok_colunas' as item, case when (select count(*) from information_schema.columns where table_schema = 'public' and table_name = 'character_sheets' and column_name in ('vitals_version', 'operacoes')) = 2 then 'sim' else 'não' end as valor
union all select 'ok_gatilho_vitais', case when exists (select 1 from pg_trigger where tgrelid = 'public.character_sheets'::regclass and tgname = 'character_sheets_vitais' and not tgisinternal) then 'sim' else 'não' end
union all select 'ok_funcoes_so_autenticado', case when (select bool_and(has_function_privilege('authenticated', f, 'execute') and not has_function_privilege('anon', f, 'execute'))
    from unnest(array['public.alterar_vitais(uuid, jsonb, uuid)', 'public.usar_consumivel(uuid, text, integer, integer, uuid)', 'public.transferir_item(uuid, uuid, text, integer, uuid)']::regprocedure[]) f) then 'sim' else 'não' end
union all select 'ok_marcador_fechado', case when not has_schema_privilege('authenticated', 'private_ficha', 'usage') and not has_table_privilege('authenticated', 'private_ficha.operacao', 'select, insert, update, delete') then 'sim' else 'não' end
union all select 'ok_definer_com_search_path_fixo', case when not exists (select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname in ('private', 'private_ficha', 'public') and p.prosecdef and p.proname in ('alterar_vitais', 'usar_consumivel', 'transferir_item', 'travar', 'gravar', 'preservar_vitais', 'guarda_entregas', 'atualizar_apresentacao') and not exists (select 1 from unnest(coalesce(p.proconfig, '{}')) c where c like 'search_path=%')) then 'sim' else 'não' end
union all select 'ok_escrita_direta_limitada', case when not has_column_privilege('authenticated', 'public.character_sheets', 'vitals_version', 'update') and not has_column_privilege('authenticated', 'public.character_sheets', 'operacoes', 'update') then 'sim' else 'não' end
union all select 'ok_realtime', case when not exists (select 1 from pg_publication where pubname = 'supabase_realtime') or exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'character_sheets') then 'sim' else 'não' end
union all select 'ok_rls_ligada', case when (select relrowsecurity from pg_class where oid = 'public.character_sheets'::regclass) then 'sim' else 'não' end
union all select 'ok_item_de_origem', case when exists (select 1 from private_ficha.itens_livres where item_id = 'background-trinket') then 'sim' else 'não' end
union all select 'fichas', count(*)::text from public.character_sheets
union all select 'digital_fichas', coalesce(md5(string_agg(character_id::text || ':' || revision || ':' || md5(draft::text), ',' order by character_id)), 'vazio') from public.character_sheets
union all select 'digital_notas', coalesce(md5(string_agg(id::text || ':' || md5(coalesce(title, '') || visibility || meta::text || coalesce(body, '')), ',' order by id)), 'vazio') from public.notes;
